from sglang.srt.debug_utils.comparator.unshard.types import AxisInfo

# Recognized keys carrying per-rank parallelism metadata, in priority order.
_RECOGNIZED_KEYS = ("sglang_parallel_info", "megatron_parallel_info")

# Mapping from a parallelism axis to its (rank_field, size_field) in the raw metadata.
_AXIS_FIELDS: dict[ParallelAxis, tuple[str, str]] = {
    ParallelAxis.TP: ("tp_rank", "tp_size"),
    ParallelAxis.CP: ("cp_rank", "cp_size"),
}


def normalize_parallel_info(meta: dict) -> dict[ParallelAxis, AxisInfo]:
    """Extract unified parallelism axis information from a rank's metadata dict.

    Reads from either ``sglang_parallel_info`` or ``megatron_parallel_info`` and
    maps the known rank/size fields onto :class:`ParallelAxis` values. Axes with
    ``axis_size == 1`` are excluded, and an empty dict is returned when neither
    recognized key is present.
    """
    present_keys = [key for key in _RECOGNIZED_KEYS if key in meta]

    if len(present_keys) > 1:
        raise ValueError(
            f"Found multiple parallel_info keys in meta: {present_keys}"
        )

    if not present_keys:
        return {}

    raw = meta[present_keys[0]]

    result: dict[ParallelAxis, AxisInfo] = {}
    for axis, (rank_field, size_field) in _AXIS_FIELDS.items():
        if rank_field not in raw or size_field not in raw:
            continue
        axis_size = raw[size_field]
        if axis_size == 1:
            continue
        result[axis] = AxisInfo(axis_rank=raw[rank_field], axis_size=axis_size)

    return result
