from sglang.srt.debug_utils.comparator.dims import DimSpec, ParallelAxis
from sglang.srt.debug_utils.comparator.unshard.types import (
    AxisInfo,
    UnshardParams,
    UnshardPlan,
)


def compute_unshard_plan(
    dim_specs: list[DimSpec],
    parallel_infos: list[dict[ParallelAxis, AxisInfo]],
) -> Optional[UnshardPlan]:
    """Compute an :class:`UnshardPlan` from tensor dim specs and per-rank info.

    ``parallel_infos`` is indexed by world rank: ``parallel_infos[w]`` holds the
    parallelism metadata for world rank ``w``.
    """
    if not parallel_infos:
        raise ValueError("parallel_infos must not be empty")

    sharded_dims = [
        (dim, spec.parallel)
        for dim, spec in enumerate(dim_specs)
        if spec.parallel is not None
    ]

    if not sharded_dims:
        return None

    distinct_axes = {axis for _, axis in sharded_dims}
    if len(distinct_axes) > 1:
        raise NotImplementedError(
            f"Multi-axis unshard is not supported; found axes {sorted(a.value for a in distinct_axes)}"
        )

    dim, axis = sharded_dims[0]

    axis_sizes = {
        info[axis].axis_size for info in parallel_infos if axis in info
    }
    if not axis_sizes:
        raise ValueError(f"No parallel_info found for axis {axis.value}")
    if len(axis_sizes) > 1:
        raise ValueError(
            f"Inconsistent axis_size for axis {axis.value}: {sorted(axis_sizes)}"
        )
    axis_size = axis_sizes.pop()

    world_ranks_by_axis_rank: list[Optional[int]] = [None] * axis_size
    for world_rank, info in enumerate(parallel_infos):
        if axis not in info:
            continue
        world_ranks_by_axis_rank[info[axis].axis_rank] = world_rank

    return UnshardPlan(
        axis=axis,
        params=UnshardParams(dim=dim),
        world_ranks_by_axis_rank=world_ranks_by_axis_rank,
    )
